'use strict';
class PetPhotoEditor {
  constructor(onApply){
    this.onApply=onApply;this.crop={x:0,y:0,w:1,h:1};this.tool='crop';this.history=[];
    this.base=document.createElement('canvas');this.mask=document.createElement('canvas');this.view=document.getElementById('edit-canvas');this.dialog=document.getElementById('photo-editor');
    document.querySelectorAll('[data-tool]').forEach(b=>b.onclick=()=>{this.tool=b.dataset.tool;this.updateTools();});
    this.view.onpointerdown=e=>this.down(e);this.view.onpointermove=e=>this.move(e);this.view.onpointerup=e=>this.up(e);this.view.onpointercancel=()=>{this.drag=null;};
    document.getElementById('edit-cancel').onclick=()=>this.dialog.close();
    document.getElementById('edit-apply').onclick=()=>{this.crop={...this.draftCrop};this.mask.getContext('2d').clearRect(0,0,this.mask.width,this.mask.height);this.mask.getContext('2d').drawImage(this.draftMask,0,0);this.dialog.close();this.onApply();};
    document.getElementById('edit-reset-crop').onclick=()=>{this.saveUndo();this.draftCrop={x:0,y:0,w:1,h:1};this.draw();};
    document.getElementById('edit-undo').onclick=()=>{const h=this.history.pop();if(h){this.draftCrop=h.crop;this.draftMask.getContext('2d').putImageData(h.mask,0,0);this.draw();}};
    document.getElementById('edit-restore-all').onclick=()=>{this.saveUndo();const c=this.draftMask.getContext('2d');c.fillStyle='white';c.fillRect(0,0,this.base.width,this.base.height);this.draw();};
    document.getElementById('edit-auto').onclick=()=>this.removePlain();
    for(const key of ['x','y','w','h'])document.getElementById('crop-'+key).onchange=()=>this.numericCrop(key);
  }
  setSource(image){
    if(this.dialog.open)this.dialog.close();const scale=Math.min(1,900/Math.max(image.naturalWidth,image.naturalHeight));this.base.width=Math.max(1,Math.round(image.naturalWidth*scale));this.base.height=Math.max(1,Math.round(image.naturalHeight*scale));this.base.getContext('2d').drawImage(image,0,0,this.base.width,this.base.height);
    this.mask.width=this.base.width;this.mask.height=this.base.height;this.mask.getContext('2d').fillStyle='white';this.mask.getContext('2d').fillRect(0,0,this.mask.width,this.mask.height);this.crop={x:0,y:0,w:1,h:1};
  }
  open(tool='crop'){
    if(!this.base.width)return;this.tool=tool;this.history=[];this.draftCrop={...this.crop};this.draftMask=document.createElement('canvas');this.draftMask.width=this.base.width;this.draftMask.height=this.base.height;this.draftMask.getContext('2d').drawImage(this.mask,0,0);this.view.width=this.base.width;this.view.height=this.base.height;this.updateTools();this.draw();this.dialog.showModal();
  }
  updateTools(){document.querySelectorAll('[data-tool]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.tool===this.tool)));document.getElementById('edit-help').textContent={crop:'Drag a box around your pet. Include the ears! Or enter crop percentages below.',erase:'Paint over background to leave it unstitched. Checkerboard means bare fabric.',restore:'Paint to restore fur, eyes or any detail removed by mistake.'}[this.tool];}
  saveUndo(){this.history.push({crop:{...this.draftCrop},mask:this.draftMask.getContext('2d').getImageData(0,0,this.base.width,this.base.height)});if(this.history.length>8)this.history.shift();}
  point(e){const r=this.view.getBoundingClientRect();return {x:Math.max(0,Math.min(this.base.width,(e.clientX-r.left)*this.base.width/r.width)),y:Math.max(0,Math.min(this.base.height,(e.clientY-r.top)*this.base.height/r.height))};}
  down(e){if(e.button!==0)return;e.preventDefault();this.saveUndo();const p=this.point(e);this.drag={start:p,last:p};this.view.setPointerCapture(e.pointerId);if(this.tool!=='crop')this.paint(p,p);}
  move(e){if(!this.drag)return;const p=this.point(e);if(this.tool==='crop'){const a=this.drag.start;this.draftCrop={x:Math.min(a.x,p.x)/this.base.width,y:Math.min(a.y,p.y)/this.base.height,w:Math.max(1,Math.abs(a.x-p.x))/this.base.width,h:Math.max(1,Math.abs(a.y-p.y))/this.base.height};}else this.paint(this.drag.last,p);this.drag.last=p;this.draw();}
  up(e){if(!this.drag)return;this.move(e);if(this.tool==='crop'&&(this.draftCrop.w*this.base.width<12||this.draftCrop.h*this.base.height<12)){const previous=this.history.pop();this.draftCrop=previous.crop;}this.drag=null;this.draw();}
  paint(a,b){const ctx=this.draftMask.getContext('2d'),r=this.draftCrop;ctx.save();ctx.beginPath();ctx.rect(r.x*this.base.width,r.y*this.base.height,r.w*this.base.width,r.h*this.base.height);ctx.clip();ctx.globalCompositeOperation=this.tool==='erase'?'destination-out':'source-over';ctx.strokeStyle=ctx.fillStyle='white';ctx.lineCap='round';ctx.lineWidth=+document.getElementById('brush-size').value/100*Math.max(this.base.width,this.base.height);ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);ctx.stroke();ctx.beginPath();ctx.arc(b.x,b.y,ctx.lineWidth/2,0,Math.PI*2);ctx.fill();ctx.restore();this.draw();}
  numericCrop(key){this.saveUndo();const r={...this.draftCrop};const input=document.getElementById('crop-'+key),n=Number(input.value)/100;if(!Number.isFinite(n)){this.draw();return;}r[key]=n;r.x=Math.max(0,Math.min(.98,r.x));r.y=Math.max(0,Math.min(.98,r.y));r.w=Math.max(.02,Math.min(1-r.x,r.w));r.h=Math.max(.02,Math.min(1-r.y,r.h));this.draftCrop=r;this.draw();}
  removePlain(){this.saveUndo();const {width:w,height:h}=this.base,data=this.base.getContext('2d').getImageData(0,0,w,h);const removed=ThreadformEngine.plainBackground(data.data,w,h,this.draftCrop,+document.getElementById('background-tolerance').value);const ctx=this.draftMask.getContext('2d'),m=ctx.getImageData(0,0,w,h);let count=0;for(let i=0;i<removed.length;i++)if(removed[i]){m.data[i*4+3]=0;count++;}ctx.putImageData(m,0,0);this.tool='restore';this.updateTools();this.draw();document.getElementById('edit-help').textContent=count?'Check ears and pale fur. Restore anything removed by mistake, or undo.':'No matching edge background found. Use the erase brush instead.';}
  draw(){const ctx=this.view.getContext('2d'),w=this.base.width,h=this.base.height,r=this.draftCrop;ctx.clearRect(0,0,w,h);ctx.drawImage(this.base,0,0);ctx.globalCompositeOperation='destination-in';ctx.drawImage(this.draftMask,0,0);ctx.globalCompositeOperation='source-over';ctx.fillStyle='#17382c99';const x=r.x*w,y=r.y*h,cw=r.w*w,ch=r.h*h;ctx.fillRect(0,0,w,y);ctx.fillRect(0,y+ch,w,h-y-ch);ctx.fillRect(0,y,x,ch);ctx.fillRect(x+cw,y,w-x-cw,ch);ctx.strokeStyle='white';ctx.lineWidth=Math.max(w,h)/260;ctx.setLineDash([8,5]);ctx.strokeRect(x,y,cw,ch);ctx.setLineDash([]);for(const k of ['x','y','w','h'])document.getElementById('crop-'+k).value=Math.round(r[k]*1000)/10;document.getElementById('edit-undo').disabled=!this.history.length;}
  raster(w,h,withMask=true){const full=document.createElement('canvas');full.width=this.base.width;full.height=this.base.height;const fc=full.getContext('2d');fc.drawImage(this.base,0,0);if(withMask){fc.globalCompositeOperation='destination-in';fc.drawImage(this.mask,0,0);}const out=document.createElement('canvas');out.width=w;out.height=h;const r=this.crop;out.getContext('2d').drawImage(full,r.x*full.width,r.y*full.height,r.w*full.width,r.h*full.height,0,0,w,h);return out;}
}
